<div class="auth-wrap"><div class="card auth-card p-4"><a class="auth-logo" href="<?=h(url_to(''))?>"><img src="<?=h(brand_logo_url(false, true))?>" alt="<?=h(setting('site_name', 'o2o云'))?>" height="48"></a><h2>注册</h2><form method="post"><?=csrf_field()?><input class="form-control mb-2" name="username" placeholder="用户名" required><input class="form-control mb-2" name="email" type="email" placeholder="邮箱" required><input class="form-control mb-1" name="password" type="password" minlength="8" maxlength="64" autocomplete="new-password" placeholder="密码" required><div class="form-text mb-2">8-64 位，必须同时包含字母和数字，不能与用户名或邮箱相同。</div><input class="form-control mb-2" name="password2" type="password" minlength="8" maxlength="64" autocomplete="new-password" placeholder="确认密码" required><?php if (captcha_enabled()): ?><div class="d-flex gap-2 mb-2"><input class="form-control" name="captcha" placeholder="验证码" required><img class="captcha-img" src="<?=h(url_to('index/auth/captcha', ['scene' => 'register']))?>"></div><?php endif; ?><?php if (setting('reg_email_verify', '0') === '1'): ?><div class="input-group mb-3"><input class="form-control" name="email_code" placeholder="邮箱验证码" required><button type="button" class="btn btn-outline-secondary" data-sendcode="<?=h(url_to('index/auth/sendcode'))?>">发送验证码</button></div><?php endif; ?><button class="btn btn-primary w-100">注册</button></form></div></div>
